<template>
<section><div v-if="loading" class="state-card"><span class="spinner"></span><p>{{ t('loading') }}</p></div><div v-else-if="error" class="feedback error">{{ error }}</div><template v-else-if="customer"><RouterLink class="back-link" to="/customers">{{ t('back') }}</RouterLink><div class="details-heading"><div><span class="eyebrow">{{ t('details') }}</span><h1>{{ customer.name }}</h1><p class="muted">{{ t('manage') }}</p></div><div><button class="ghost-btn" @click="goEdit">{{ t('edit') }}</button><button class="danger-btn" @click="showDelete=true">{{ t('delete') }}</button></div></div><div class="details-grid"><article class="detail-card"><span class="detail-label">{{ t('companyInfo') }}</span><h3>{{ customer.name }}</h3><dl><div><dt>{{ t('industry') }}</dt><dd>{{ customer.industry || t('notSpecified') }}</dd></div><div><dt>{{ t('email') }}</dt><dd>{{ customer.email || t('notSpecified') }}</dd></div><div><dt>{{ t('phone') }}</dt><dd>{{ customer.phone || t('notSpecified') }}</dd></div><div><dt>{{ t('address') }}</dt><dd>{{ customer.address || t('notSpecified') }}</dd></div></dl></article><article class="detail-card"><span class="detail-label">{{ t('recordInfo') }}</span><dl><div><dt>{{ t('created') }}</dt><dd>{{ formatDate(customer.created_at) }}</dd></div><div><dt>{{ t('updated') }}</dt><dd>{{ formatDate(customer.updated_at) }}</dd></div><div><dt>{{ t('id') }}</dt><dd class="id-value">{{ customer.id }}</dd></div></dl></article></div></template><div v-if="showDelete" class="modal-backdrop" @click.self="showDelete=false"><section class="modal-card confirm-card"><div class="warning-icon">!</div><h2>{{ t('deleteQuestion') }}</h2><p class="muted">{{ t('deleteText') }} <strong>{{ customer?.name }}</strong>.</p><div class="form-actions"><button class="ghost-btn" @click="showDelete=false">{{ t('cancel') }}</button><button class="danger-btn" :disabled="deleting" @click="remove">{{ deleting ? '…' : t('confirmDelete') }}</button></div></section></div></section>
</template>
<script setup>
import { ref, onMounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { customerService } from '../services/customers'
import { t } from '../i18n'
const route=useRoute(),router=useRouter(),customer=ref(null),loading=ref(true),error=ref(''),showDelete=ref(false),deleting=ref(false)
async function load(){try{customer.value=await customerService.get(route.params.id)}catch(e){error.value=e.message}finally{loading.value=false}}onMounted(load)
function goEdit(){router.push({path:'/customers',query:{edit:customer.value.id}})}async function remove(){deleting.value=true;try{await customerService.remove(customer.value.id);router.push('/customers')}catch(e){error.value=e.message;showDelete.value=false}finally{deleting.value=false}}function formatDate(v){return v?new Date(v).toLocaleDateString(localStorage.getItem('smart_crm_locale')==='en'?'en-US':'uk-UA',{day:'2-digit',month:'long',year:'numeric'}):'—'}
</script>

